-- Run once (seed_runs). Kerala Tier A leaders, generated by scraper/src/bihar/leaders-cli.ts from the curated
-- scraper/data/kl/leaders.json and leader-profiles.json: candidacy links (never moving curated or merged
-- persons), fill-only profile fields, and the leaders/cabinet watchlists of each Kerala manifest (written once;
-- admins edit them afterwards). Persons and image credits above the guard are idempotent and run every time.
SELECT NOT EXISTS (SELECT 1 FROM seed_runs WHERE name = 'seed_kl_leaders')
   AS seed_apply \gset
\if :seed_apply

-- Link each leader's candidacies to the best-linked person. A candidacy moves from a one-candidacy person or from a
-- person whose candidacies all belong to this leader (leaders.json is curated); never from a merge, a split or a
-- person with an admin-entered profile.
UPDATE candidates c SET person_id = (SELECT c.person_id FROM candidates c WHERE c.id IN ('1c1b70b5-578c-4c85-a2b3-a2c44d4ba7da', '60071d37-30ba-47d6-a3c9-02922d0822ff', '80f776cb-1d41-5f09-a743-029806eb0389') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1)
WHERE c.id IN ('1c1b70b5-578c-4c85-a2b3-a2c44d4ba7da', '60071d37-30ba-47d6-a3c9-02922d0822ff', '80f776cb-1d41-5f09-a743-029806eb0389') AND c.person_id <> (SELECT c.person_id FROM candidates c WHERE c.id IN ('1c1b70b5-578c-4c85-a2b3-a2c44d4ba7da', '60071d37-30ba-47d6-a3c9-02922d0822ff', '80f776cb-1d41-5f09-a743-029806eb0389') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1)
  AND ((SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) = 1
       OR NOT EXISTS (SELECT 1 FROM candidates c3 WHERE c3.person_id = c.person_id AND c3.id NOT IN ('1c1b70b5-578c-4c85-a2b3-a2c44d4ba7da', '60071d37-30ba-47d6-a3c9-02922d0822ff', '80f776cb-1d41-5f09-a743-029806eb0389')))
  AND NOT EXISTS (SELECT 1 FROM person_merges pm WHERE pm.duplicate->>'id' = c.person_id::text OR pm.keeper_ref = c.person_id)
  AND NOT EXISTS (SELECT 1 FROM audit_logs al WHERE al.action = 'CANDIDATE_SPLIT' AND al.entity_type = 'candidate' AND al.entity_id = c.id::text)
  AND NOT EXISTS (SELECT 1 FROM persons pp WHERE pp.id = c.person_id AND (pp.photo_url IS NOT NULL OR pp.bio IS NOT NULL OR pp.wikipedia_url IS NOT NULL OR pp.date_of_birth IS NOT NULL));
