UPDATE candidates c SET person_id = (SELECT c.person_id FROM candidates c WHERE c.id IN ('6fdc0965-e6f3-4972-8df6-e2b56fd1cac1', '8c48a2e3-b731-4444-a1f1-0f09068b8428', '98d4cb54-3a07-4b92-b267-8120221c6c50', 'b19b2b90-ee62-52a2-969b-00d8187d9751') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1)
WHERE c.id IN ('6fdc0965-e6f3-4972-8df6-e2b56fd1cac1', '8c48a2e3-b731-4444-a1f1-0f09068b8428', '98d4cb54-3a07-4b92-b267-8120221c6c50', 'b19b2b90-ee62-52a2-969b-00d8187d9751') AND c.person_id <> (SELECT c.person_id FROM candidates c WHERE c.id IN ('6fdc0965-e6f3-4972-8df6-e2b56fd1cac1', '8c48a2e3-b731-4444-a1f1-0f09068b8428', '98d4cb54-3a07-4b92-b267-8120221c6c50', 'b19b2b90-ee62-52a2-969b-00d8187d9751') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1)
  AND ((SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) = 1
       OR NOT EXISTS (SELECT 1 FROM candidates c3 WHERE c3.person_id = c.person_id AND c3.id NOT IN ('6fdc0965-e6f3-4972-8df6-e2b56fd1cac1', '8c48a2e3-b731-4444-a1f1-0f09068b8428', '98d4cb54-3a07-4b92-b267-8120221c6c50', 'b19b2b90-ee62-52a2-969b-00d8187d9751')))
  AND NOT EXISTS (SELECT 1 FROM person_merges pm WHERE pm.duplicate->>'id' = c.person_id::text OR pm.keeper_ref = c.person_id)
  AND NOT EXISTS (SELECT 1 FROM audit_logs al WHERE al.action = 'CANDIDATE_SPLIT' AND al.entity_type = 'candidate' AND al.entity_id = c.id::text)
  AND NOT EXISTS (SELECT 1 FROM persons pp WHERE pp.id = c.person_id AND (pp.photo_url IS NOT NULL OR pp.bio IS NOT NULL OR pp.wikipedia_url IS NOT NULL OR pp.date_of_birth IS NOT NULL));

